document.addEventListener("DOMContentLoaded",(function(){const t=document.getElementById("countryDisplay");chrome.storage.local.get("detectedCountry",(function(e){e.detectedCountry?t.textContent=`Country: ${e.detectedCountry}`:t.textContent="Waiting..."})),chrome.storage.local.get("mapstringS",(function(t){document.getElementById("frame").setAttribute("src",`${t.mapstringS}`)})),chrome.runtime.onMessage.addListener((e=>{"updateCountry"===e.action&&(t.textContent=`Country: ${e.fullCountry}`,chrome.storage.local.set({detectedCountry:e.fullCountry}))})),chrome.storage.onChanged.addListener(((e,n)=>{"local"===n&&e.detectedCountry&&(t.textContent=`Country: ${e.detectedCountry.newValue}`),"local"===n&&e.mapstringS&&document.getElementById("frame").setAttribute("src",`${e.mapstringS.newValue}`)}))}));